/**
 * Private guards for the ids a change points at: assignees and project leads,
 * labels, parent issues, reply targets and mentioned members.
 *
 * Everything a change references must be usable from the workspace the change
 * is made in. A row that lives in another organization is refused through
 * `assertOrgScope()` / `assertRowsInScope()`, exactly like any other
 * cross-tenant access; a reference that is missing, archived, not a current
 * member or otherwise not a valid target is a `NotFoundError`. Services run
 * these before any write, so a refused change leaves nothing behind.
 */
import { isArchived, isLive } from "@/lib/soft-delete";
import { assertOrgScope, assertRowsInScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError, requireFound } from "./_support";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Actor, Member, MemberWithUser } from "@/types/member";

/** Page size used when walking the whole member list. */
const MEMBER_PAGE_SIZE = 100;

/**
 * A current member can act in the organization: not removed (soft deleted),
 * not suspended, not still pending an invitation.
 */
export function isCurrentMember(member: Member): boolean {
  return member.status === "active" && isLive(member);
}

/** Throws `NotFoundError` unless `userId` is a current member of `orgId`. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || !isCurrentMember(member)) {
    throw new NotFoundError("Member", userId);
  }
}

/** Every current member of `orgId`, joined with their user record. */
export async function listCurrentMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  do {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MEMBER_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items.filter(isCurrentMember));
    cursor = page.nextCursor;
  } while (cursor !== null);

  return members;
}

/**
 * Checks that every label id names one of the actor's organization's labels
 * and returns the ids de-duplicated, ready to be written.
 */
export async function requireOrgLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<readonly LabelId[]> {
  const unique = [...new Set(labelIds)];
  if (unique.length === 0) return unique;

  const found = await labelRepo.locateLabelsByIds(unique);
  assertRowsInScope(actor, found);

  const known = new Set<string>(found.map((label) => label.id));
  const missing = unique.find((labelId) => !known.has(labelId));
  if (missing !== undefined) {
    throw new NotFoundError("Label", missing);
  }

  return unique;
}

/** A parent issue must be a live issue of the same project. */
export async function assertParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.locateIssueById(parentId),
    "Issue",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);

  if (parent.projectId !== projectId || isArchived(parent)) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** A reply must answer a live, top-level comment on the same issue. */
export async function assertReplyTarget(
  actor: Actor,
  issueId: IssueId,
  parentId: CommentId,
): Promise<void> {
  const parent = requireFound(
    await commentRepo.locateCommentById(parentId),
    "Comment",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);

  if (
    parent.issueId !== issueId ||
    isArchived(parent) ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}

