import { beforeAll, afterAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("$P/tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("$P/tests/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("$P/tests/server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import * as memberService from "@/server/services/member-service";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { getDb, issueLabels } from "@/server/db";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";
import type { Tenant } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
let a: Tenant; let b: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); a = await createTenant("refa"); b = await createTenant("refb"); });
afterAll(() => cleanup());

describe("references", () => {
  it("labels", async () => {
    const own = await labelRepo.insertLabel({ orgId: a.org.id, name: "own", color: "#000000", description: null });
    const foreign = await labelRepo.insertLabel({ orgId: b.org.id, name: "foreign", color: "#000000", description: null });
    const before = await issueRepo.countIssues(a.org.id, a.project.id);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: [foreign.id] })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: ["01HZZZNOPENOPENOPENOPENOPE" as never] })).rejects.toBeInstanceOf(NotFoundError);
    expect(await issueRepo.countIssues(a.org.id, a.project.id)).toBe(before);
    const issue = await issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: [own.id, own.id] });
    expect(issue.labelIds).toEqual([own.id]);
    await expect(issueService.updateIssue(a.actors.member, { orgId: a.org.id, issueId: issue.id, title: "changed", labelIds: [foreign.id] })).rejects.toBeInstanceOf(TenantScopeError);
    const reread = await issueService.getIssue(a.actors.member, a.org.id, issue.id);
    expect(reread.issue.title).not.toBe("changed");
    expect(reread.labels.map((l) => l.id)).toEqual([own.id]);
    // stale foreign join row never shows
    getDb().insert(issueLabels).values({ orgId: a.org.id, issueId: issue.id, labelId: foreign.id }).run();
    const again = await issueService.getIssue(a.actors.member, a.org.id, issue.id);
    expect(again.labels.map((l) => l.id)).toEqual([own.id]);
    expect(again.issue.labelIds).toEqual([own.id]);
  });

  it("parents", async () => {
    const other = await projectService.createProject(a.actors.owner, { orgId: a.org.id, name: "Other proj", slug: "other", key: "OTH", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
    const parentOk = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const parentOther = await issueService.createIssue(a.actors.member, issueInput(a.org.id, other.id));
    const parentForeign = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id));
    const parentArchived = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    await issueService.archiveIssue(a.actors.owner, a.org.id, parentArchived.id);
    const child = await issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parentOk.id });
    expect(child.parentId).toBe(parentOk.id);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parentForeign.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parentOther.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parentArchived.id })).rejects.toBeInstanceOf(NotFoundError);
  });

  it("replies", async () => {
    const i1 = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const i2 = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const top = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i1.id, body: "top", parentId: null, mentionedUserIds: [] });
    const reply = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i1.id, body: "reply", parentId: top.id, mentionedUserIds: [] });
    await expect(commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i1.id, body: "r2", parentId: reply.id, mentionedUserIds: [] })).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i2.id, body: "r3", parentId: top.id, mentionedUserIds: [] })).rejects.toBeInstanceOf(NotFoundError);
    const del = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i1.id, body: "del", parentId: null, mentionedUserIds: [] });
    await commentService.deleteComment(a.actors.owner, { orgId: a.org.id, commentId: del.id });
    await expect(commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i1.id, body: "r4", parentId: del.id, mentionedUserIds: [] })).rejects.toBeInstanceOf(NotFoundError);
    const bi = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id));
    const bc = await commentService.createComment(b.actors.member, { orgId: b.org.id, issueId: bi.id, body: "b", parentId: null, mentionedUserIds: [] });
    await expect(commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: i1.id, body: "r5", parentId: bc.id, mentionedUserIds: [] })).rejects.toBeInstanceOf(TenantScopeError);
    expect(await commentService.getThread(a.actors.member, a.org.id, i1.id)).toHaveLength(2);
  });

  it("members", async () => {
    const stranger = await userRepo.insertUser({ email: "stranger@x.test", name: "s", passwordHash: "x" });
    const leaver = await userRepo.insertUser({ email: "leaver@refa.test", name: "l", passwordHash: "x" });
    const m = await memberRepo.insertMember(a.org.id, leaver.id, "member", null);
    await memberService.removeMember(a.actors.owner, { orgId: a.org.id, memberId: m.id });
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id));
    const events: unknown[] = [];
    const off = subscribe("issue.assigned", (p) => { events.push(p); });
    await expect(issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: stranger.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: b.userIds.member })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: leaver.id })).rejects.toBeInstanceOf(NotFoundError);
    off();
    expect(events).toHaveLength(0);
    await expect(issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { assigneeId: stranger.id }))).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.createProject(a.actors.owner, { orgId: a.org.id, name: "Strange", slug: "strange", key: "STR", description: null, visibility: "org", leadId: stranger.id, color: "#6366f1", targetDate: null })).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.updateProject(a.actors.owner, { orgId: a.org.id, projectId: a.project.id, leadId: leaver.id })).rejects.toBeInstanceOf(NotFoundError);
    const ok = await issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: a.userIds.viewer });
    expect(ok.assigneeId).toBe(a.userIds.viewer);

    const c = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: issue.id, body: "hey @leaver @admin @stranger", parentId: null, mentionedUserIds: [leaver.id, stranger.id, b.userIds.owner, a.userIds.owner] });
    expect([...c.mentionedUserIds].sort()).toEqual([a.userIds.admin, a.userIds.owner].sort());
    const n = await notificationRepo.listNotifications({ orgId: a.org.id, recipientId: leaver.id, limit: 25, cursor: null } as never);
    expect(n.items).toHaveLength(0);
  });
});
EOF
